 if path in {'tests/governance/test_recovery_oauth_code_ci.py','tests/governance/native-directory-transports-source-v1.json'}:
  if type(raw)is not bytes or raw!=(ROOT/path).read_bytes():raise ValueError('unknown current test view')
  raw=n05_delta._normalize_metadata(path,raw)
 if path in legacy_view.METADATA_PATHS:return legacy_view.historical_metadata_source(path,raw)
 if path=="tests/governance/test_recovery_oauth_code_ci.py":
  current=n05_delta.REPLACEMENTS[path][0][0]
  if type(raw)is not bytes or raw!=current or hashlib.sha256(raw).hexdigest()!=n05_delta.legacy.SOURCE_INPUTS[path]or hashlib.sha256(PREVIOUS_RECIPE_CODE_CI).hexdigest()!=delta.SOURCE_INPUTS[path]:raise ValueError("unreviewed lifecycle CI test metadata")
  return PREVIOUS_RECIPE_CODE_CI
 # One exact audit-metadata view only; real N01 source inventory remains current.
 selected='tests/governance/native-directory-transports-source-v1.json'
